// client/src/features/dashboard/attendee/AttendeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  // 1️⃣ Fetch all events with your registration/payment status
  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get(
        '/api/attendee/events',              // <-- Uses CRA proxy
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEvents(res.data.events);
      setError(null);
    } catch {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchEvents(); }, []);

  // 2️⃣ Register handler
  const handleRegister = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        '/api/attendee/register',
        { eventId: id },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Registration failed');
    }
  };

  // 3️⃣ Pay handler
  const handlePay = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        `/api/attendee/pay/${id}`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Payment failed');
    }
  };

  // 4️⃣ Split into three lists
  const upcoming   = events.filter(e => !e.isRegistered);
  const registered = events.filter(e => e.isRegistered && !e.hasPaid);
  const paid       = events.filter(e => e.hasPaid);

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {/* Upcoming */}
        <section>
          <h3>Upcoming Events</h3>
          {loading
            ? <p>Loading…</p>
            : error
              ? <p style={{ color:'red' }}>{error}</p>
              : upcoming.length === 0
                ? <p>No upcoming events.</p>
                : (
                  <ul style={{ listStyle:'none', padding:0 }}>
                    {upcoming.map(evt => (
                      <li key={evt.id} style={{ margin:'1rem 0' }}>
                        <strong>{evt.title}</strong><br/>
                        <small>{new Date(evt.date).toLocaleString()}</small>
                        <div style={{ marginTop:'0.5rem' }}>
                          <button className="btn" onClick={() => handleRegister(evt.id)}>
                            Register
                          </button>
                        </div>
                      </li>
                    ))}
                  </ul>
                )
          }
        </section>

        {/* Registered but not paid */}
        <section style={{ marginTop:'2rem' }}>
          <h3>Pending Payment</h3>
          {registered.length === 0
            ? <p>No registrations pending payment.</p>
            : (
              <ul style={{ listStyle:'none', padding:0 }}>
                {registered.map(evt => (
                  <li key={evt.id} style={{ margin:'1rem 0' }}>
                    <strong>{evt.title}</strong><br/>
                    <small>{new Date(evt.date).toLocaleString()}</small>
                    <div style={{ marginTop:'0.5rem' }}>
                      <button className="btn" onClick={() => handlePay(evt.id)}>
                        Pay Now
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            )
          }
        </section>

        {/* Paid */}
        <section style={{ marginTop:'2rem' }}>
          <h3>Registered & Paid</h3>
          {paid.length === 0
            ? <p>No paid events yet.</p>
            : (
              <ul style={{ listStyle:'none', padding:0 }}>
                {paid.map(evt => (
                  <li key={evt.id} style={{ margin:'1rem 0' }}>
                    <strong>{evt.title}</strong><br/>
                    <small>{new Date(evt.date).toLocaleString()}</small>
                    <div style={{ marginTop:'0.5rem' }}>
                      <Link
                        to={`/join?link=${encodeURIComponent(evt.sessionLink)}`}
                        className="btn"
                      >
                        Join Session
                      </Link>
                    </div>
                  </li>
                ))}
              </ul>
            )
          }
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
